import { useState, useEffect } from "react";
import { Typography, Card, CardContent, Slide } from "@mui/material";
import Grid from "@mui/material/Unstable_Grid2";
import { AccountCircle } from "@mui/icons-material";
import { Helmet } from "react-helmet-async";
import worldMap from "../assets/map.svg";
import { CustomDivider } from "../components/common";
import { ContactForm } from "../components/pages";
import { useTheme } from "@emotion/react";
import Navbar from "../containers/NavbarContainer";

const Contact = ({ helmetTitle }) => {
  const [loading, setLoading] = useState(false);
  const theme = useTheme();

  useEffect(() => {
    setLoading(true);

    return () => {
      setLoading(false);
    };
  }, []);

  return (
    <>
      <Navbar />
      <Card
        sx={{
          height: "100vh",
          overflowY: "scroll",
          display: "flex",
          flexDirection: "column",
          background: theme.palette.mode === "dark" ? "#111827" : "#F8FAFC",
        }}
      >
        <Helmet>
          <title>{helmetTitle}</title>
        </Helmet>
        <CardContent>
          <CustomDivider
            bColor="warning.main"
            cColor={theme.palette.mode === "dark" ? "#F59E0B" : "#ff7900"}
            icon={<AccountCircle />}
            align="center"
            text="ارتباط با من"
          />
          <Grid container sx={{ mt: 5 }}>
            <Slide
              direction="up"
              in={loading}
              style={{
                transitionDelay: loading ? "200ms" : "0ms",
              }}
            >
              <Grid xs={12} sx={12} md={8}>
                <Card
                  sx={{
                    justifyContent: "center",
                    alignItems: "center",
                    background: theme.palette.mode == "dark" ? "#0A1222" : "",
                    pt: 1,
                    pb: 2
                  }}
                >
                  <ContactForm />
                </Card>
              </Grid>
            </Slide>
            <Slide
              direction="up"
              in={loading}
              style={{
                transitionDelay: loading ? "200ms" : "0ms",
              }}
            >
              <Grid
                xs={0}
                sm={0}
                md={4}
                sx={{
                  textAlign: "center",
                  backgroundImage: `url(${worldMap})`,
                  backgroundRepeat: "no-repeat",
                  backgroundPosition: "center",
                }}
              >
                <Typography
                  variant="h6"
                  color="text.primary"
                  sx={{
                    fontFamily: "vazir",
                    // fontSize: "25px",
                    fontWeight: 700,
                    mt: 4,
                    display: {
                      xs: "none",
                      sm: "none",
                      md: "block",
                    },
                  }}
                >
                  بیا در مورد همه چیز باهم صحبت کنیم
                </Typography>
                <Typography
                  variant="body1"
                  color="text.primary"
                  sx={{
                    mt: 2,
                    display: {
                      xs: "none",
                      sm: "none",
                      md: "block",
                    },
                  }}
                >
                  👋{" "}
                  <a
                    href="mailto:mohammadbabakhani2003@gmail.com"
                    alt="email"
                    style={{
                      color: "tomato",
                    }}
                  >
                    ایمیل
                  </a>{" "}
                  بزن به من
                </Typography>
              </Grid>
            </Slide>
          </Grid>
        </CardContent>
      </Card>
    </>
  );
};

export default Contact;
