import { Box, Chip, Tooltip, Typography } from "@mui/material";
import DevWorkInfo from "../../constants/DevWorkInfo";
import CountUp from "react-countup";

const DevWorkCount = () => {
    return (
        <>
            {DevWorkInfo.map((item, index) => (
                <Box
                    key={index}
                    component="div"
                    sx={{ width: 1, mb: 1 }}
                >
                    <Tooltip
                        title={item.tooltipTitle}
                        placement="right"
                        arrow
                    >
                        <Chip
                            icon={item.icon}
                            label={
                                <Typography
                                    variant="body1"
                                    color="text.primary"
                                >
                                    <CountUp
                                        start={0}
                                        end={item.total}
                                        duration={2}
                                    />
                                </Typography>
                            }
                            sx={{
                                p: "14px",
                                backgroundColor: item.color,   
                                border: `2px solid ${item.colorB}`,                              
                                width: 1,
                            }}
                        />
                    </Tooltip>
                </Box>
            ))}
        </>

    )
}

export default DevWorkCount;